const g = new THREE.Group();
const white = 0xffffff;

// マテリアルを用意しておく（色と光沢を設定）
function mat(color) {
  return new THREE.MeshPhongMaterial({ color: color, flatShading: true });
}

// 頭 (上側の小さい球体)
const head = new THREE.Mesh(new THREE.SphereGeometry(0.8, 14, 10), mat(white));
head.position.y = 3.0; // 少し上に配置
g.add(head);

// 体のベース (下側の大きい球体)
const bodyBase = new THREE.Mesh(new THREE.SphereGeometry(1.2, 14, 10), mat(white));
bodyBase.position.y = 1.2; // 頭の下に配置
g.add(bodyBase);

// 鼻 (オレンジの円錐)
const nose = new THREE.Mesh(new THREE.ConeGeometry(0.15, 0.6, 8), mat(0xff8a1a));
nose.rotation.x = Math.PI / 2; // X軸を中心に90度回転させて、前を向かせる
nose.position.set(0, 3.0, 0.85); // 頭の前に配置
g.add(nose);

return g;
